const html = $input.first().json.data;

// 1. Clean the HTML
let cleanText = html.replace(/<(script|style)\b[^<]*(?:(?!<\/\1>)<[^<]*)*<\/\1>/gi, ' ');
cleanText = cleanText.replace(/&nbsp;/gi, ' ');
cleanText = cleanText.replace(/<[^>]*>?/gm, ' ');
cleanText = cleanText.replace(/\s+/g, ' ');

const results = [];

// 2. Expanded Regex to capture the description text after the date
const regex = /(RESIDENTIAL LAND|COMMERCIAL BUILDING|SINGLE FAMILY HOME|RURAL LAND|AGRICULTURAL LAND|MANUFACTURED HOME|TOWNHOUSE|ESTATE HOME|VACANT LAND|COMMERCIAL CONDO|OFFICE CONDO UNIT|LAND WITH DWELLING)\s*:\s*(.*?)\s*ONLINE AUCTION DAT\s*E:\s*([A-Za-z]+,\s*[A-Za-z]+\s*\d{1,2},\s*\d{4})(.*?)(?=(?:RESIDENTIAL LAND|COMMERCIAL BUILDING|SINGLE FAMILY HOME|RURAL LAND|AGRICULTURAL LAND|MANUFACTURED HOME|TOWNHOUSE|ESTATE HOME|VACANT LAND|COMMERCIAL CONDO|OFFICE CONDO UNIT|LAND WITH DWELLING)\s*:|$)/gi;

let match;
while ((match = regex.exec(cleanText)) !== null) {
  let address = match[2].trim();
  let saleDate = match[3].trim();
  let description = match[4] || "";

  // Hunt for the County in the description
  let countyMatch = description.match(/([A-Za-z\s]+County)/i);
  let county = countyMatch ? countyMatch[1].trim() : "N/A - Check Listing";

  results.push({
    json: {
      property_address: address,
      county: county,
      state: "",              // not published on the index page
      source: "US Treasury",
      status: "Upcoming",
      sale_date: saleDate,
      bidding_date: saleDate, // Treasury uses the same date for both
      bidding_time: "Check Listing",
      current_bid: 0,         // not published on the index page
      auction_url: "https://www.treasury.gov/auctions/treasury/rp/realprop.shtml",
      time_remaining: "",
      unique_id: ''
    }
  });
}

if (results.length === 0) {
  return [{ json: { error: "No matches found.", text_sample: cleanText.substring(0, 500) } }];
}

return results;
